package mapper;import entity.Rang;import java.sql.ResultSet;import java.sql.SQLException;public class RangMapper implements RowMapper<Rang> {    @Override    public Rang mapper(ResultSet rs) {        try {            String maRang = rs.getString("maRang");            String tenRang = rs.getString("tenRang");            String maLoaiRang = rs.getString("maLoaiRang");            return new Rang(maRang, tenRang, maLoaiRang);        } catch (SQLException e) {            return null;        }    }}